/**
 * Testplan der großen Testphase (QA-04). Eine Quelle für die Seite „Testphase“ (#/testphase), das
 * Testprotokoll und docs/testing/TESTPLAN.md (erzeugt mit `node scripts/checks/render_testplan.mjs`).
 *
 * Aufbau (Neuordnung QA-04 vom 06.11.2026): Bereiche in drei Teilen – nur im Browser, mit Minecraft (Mod),
 * mit Paper-Server (Plugin). Doppelte Fälle sind zusammengelegt, Dateiwege (Teampaket, Meldecode, Serverdatei,
 * Plan-Datei kopieren) nur noch als Notfall genannt, weil Planer, Mod und Plugin über das Internet sprechen.
 *
 * Regeln für Fälle: stabile ID (Bereichskürzel + laufende Nummer, nie umnummerieren, nie wiederverwenden),
 * Schritte so schreiben, dass jemand ohne Vorwissen sie nachmachen kann, ein beobachtbares Ergebnis nennen.
 * Wird ein Fall in einen anderen gelegt, kommt seine ID in `merged` des aufnehmenden Falls: Protokolle,
 * `?melden=<alte ID>`, Suche und Verweise in Roadmap und Doku finden ihn dann weiter.
 * „kern“ = muss jede Testrunde einmal laufen; „vertieft“ = wenn Zeit ist oder der Bereich geändert wurde.
 */
export type TestLevel = 'kern' | 'vertieft';

export interface TestCase {
  readonly id: string;
  readonly title: string;
  readonly steps: readonly string[];
  readonly expect: string;
  readonly level: TestLevel;
  /** Seite zum Starten, falls sinnvoll. */
  readonly start?: string;
  /** Frühere Fall-IDs, die in diesem Fall aufgegangen sind. */
  readonly merged?: readonly string[];
}

export interface TestArea {
  readonly id: string;
  readonly title: string;
  /** Planer (Browser), Mod (im Spiel) oder Server (Paper-Plugin, nur auf einem echten Server testbar). */
  readonly kind: 'planer' | 'mod' | 'server';
  readonly intro: string;
  readonly cases: readonly TestCase[];
}

interface CaseOptions { readonly start?: string; readonly merged?: readonly string[] }
const make = (level: TestLevel) => (id: string, title: string, steps: readonly string[], expect: string, opts: CaseOptions = {}): TestCase =>
  ({ id, title, steps, expect, level, ...(opts.start && { start: opts.start }), ...(opts.merged?.length && { merged: opts.merged }) });
const k = make('kern');
const v = make('vertieft');

/** Anzeigename der Art eines Bereichs. */
