export const ALL_CASES: readonly TestCase[] = TEST_AREAS.flatMap(a => a.cases);

/** Frühere Fall-ID → Fall, in dem sie aufgegangen ist (aus `merged`). */
export const MERGED_INTO: Readonly<Record<string, string>> = Object.fromEntries(ALL_CASES.flatMap(c => (c.merged ?? []).map(old => [old, c.id] as const)));

/** Aktuelle Fall-ID zu einer (auch früheren) ID; unbekannte IDs bleiben unverändert. */
export function currentCaseId(id: string): string {
  return MERGED_INTO[id] ?? id;
}

/** Fall zu einer aktuellen oder früheren ID. */
export function findCase(id: string): TestCase | undefined {
  const cur = currentCaseId(id.trim().toUpperCase());
  return ALL_CASES.find(c => c.id === cur);
}

